  "sum": "올해는 좋은 흐름이 한창일 때라 적당한 곳에서 멈추고, 낡은 방식을 고쳐 새 틀을 받아들이면 길이 열리는 해일세. 음력 3월과 7월에 이름이 알려지거나 기다리던 소식이 오고 음력 12월에는 살림이 두둑해지네.",
  "image": "옛 풀이에서는 이 괘를 '한낮 해가 기울 무렵 새 길을 고르는 모습'이라 하네. 해가 한가운데 오른 뒤 기울기 시작하듯, 좋을 때 무리하지 말고 방향을 새로 고르라는 뜻이야.",
  "chongun": "해는 한가운데 오르면 기울기 시작하고 달은 꽉 차면 줄어들기 시작하지. 올해는 바로 그 좋은 때의 꼭대기 언저리에 서 있는 해일세. 좋은 흐름도 너무 오래 끌면 흐려지니 즐거운 일이라도 끝장을 보려 하지 말고 적당할 때 멈추게. 올해는 낡은 방식을 고치거나 자리를 옮기는 쪽이 늦게라도 빛을 보네. 윗사람 뜻을 따라 새 틀을 받아들이면 길이 열리네. 봄에는 딴 사업에 눈을 돌리지 말고 여름에는 말이 많아지니 입을 단속하게. 음력 3월과 7월에는 이름이 알려지거나 기다리던 소식이 오고 음력 12월에는 살림이 두둑해지네. 음력 4월과 6월은 겉만 번지르르하고 실속이 없으니 속마음을 가볍게 털어놓지 말게. 오늘은 오래 써 온 습관 가운데 버릴 것 하나를 골라 이번 주만이라도 멈춰 보게.",
  "money": "돈은 음력 12월에 가장 두둑해지니 그때까지 분수에 맞게 쓰며 기다리게. 음력 4월에는 돈이 새거나 말이 시끄러워지기 쉬우니 씀씀이를 살피게. 음력 10월에 이득을 보려면 동쪽을 향하되 시작을 신중히 하게.",
  "work": "낡은 방식을 고치거나 자리를 옮기는 쪽이 늦게라도 빛을 보는 해일세. 윗사람의 뜻을 따라 새 틀을 받아들이면 길이 열리고, 음력 3월에 새로 시작할 일은 첫발을 떼기에 좋네. 봄에는 딴 사업에 눈을 돌리지 말고 하던 일에 힘쓰게.",
  "love": "식구끼리 오해가 쌓이기 쉬우니 서운한 말은 그날 안에 풀고 먼저 사과하는 쪽이 이기네. 가까운 사이라도 속마음은 반만 이야기하고 남의 이야기는 잘 들어 주게. 짝을 찾는 사람은 서두르지 않아야 좋은 인연이 닿네.",
  "health": "몸은 음력 6월에 조금 무거울 수 있으니 무리한 약속을 줄이고 쉬어 가게. 음력 9월에는 몸이 평탄하니 걷기와 잠 같은 기본 습관을 꾸준히 지키게. 몸이 계속 불편하면 병원에 먼저 가 보게.",
  "tips": [
   "오래 써 온 습관 하나를 골라 이번 주만이라도 멈춰 보게.",
   "서운한 일이 생기면 그날 안에 먼저 말을 건네게.",
   "겨울 들기 전에 불과 물 단속을 한 번 더 확인하게."
  ],
  "flow": "cogcocggoocg",
  "months": {
   "1": "눈이 채 녹지 않아 풀싹이 고개를 못 드는 듯 마음이 쓸쓸한 달이야. 식구끼리 오해가 쌓이기 쉬우니 서운한 말은 그날 안에 풀고 넘어가게. 먼저 사과하는 쪽이 이기는 달일세.",
   "2": "먼 길을 한 번 다녀올 일이 생기는 달이야. 그러나 새로 일을 꾸미지는 말게. 시작만 그럴듯하고 끝이 흐지부지되기 쉬우니 손해 없이 지나가는 것에 만족하게. 짐을 가볍게 꾸리고 일정에 여유를 두게.",
   "3": "생각지 못한 성과로 이름이 멀리까지 퍼지는 달일세. 귀한 사람이 찾아와 힘을 보태 주네. 동쪽과 남쪽이 좋으니 새로 시작할 일이 있다면 이달에 첫발을 떼게. 받은 도움은 잊지 말고 갚게.",
   "4": "새로 시작한 일이 자라기 버거운 달이야. 돈이 새거나 말이 시끄러워지기 쉬우니 조심하게. 방향을 잃고 헤매기 쉬우니 갈 곳이 정해지기 전에는 움직이지 말게. 서두르지 않는 것이 이달의 힘일세.",
   "5": "사람들과 어울릴 일이 많은데 좋은 일과 언짢은 일이 반반인 달이야. 입을 꼭 닫고 있으면 말다툼에 휘말리지 않네. 바깥일을 꾀하다 안의 이득을 놓치지 말고 집안일에 힘을 싣게. 집 안에 복이 고여 있는 달일세.",
   "6": "이름은 널리 퍼지는데 알맹이가 없어 허전한 달이야. 몸도 조금 무거울 수 있네. 형님 아우 하는 사이라도 속마음을 다 털어놓지 말고 한 발짝 여유를 두게. 내 이야기는 반만 하고 남의 이야기는 듣기만 하게.",
   "7": "기다리던 소식이 한 장 날아오는 달일세. 하는 일마다 좋은 기운이 붙고 자리 운도 따라오네. 다만 소식은 조금 늦게 오니 느긋하게 기다리고, 섣불리 사는 곳이나 일터를 옮기지는 말게.",
   "8": "가만히 앉아 제 할 일만 하면 복이 제 발로 찾아오는 달이야. 찾아 나서면 오히려 놓치기 쉬우니 맡은 일에 충실하게. 짝을 찾는 사람은 인연이 쉽게 닿지 않아도 서두르지 말게. 때가 되면 닿네.",
   "9": "겉은 넉넉해 보여도 속은 비어 있어 자네 마음을 헤아려 주는 사람이 드문 달이야. 조금 외로울 수 있어도 몸은 평탄하니 걱정 말게. 오지 않는 돈을 한탄하기보다 지금 가진 것을 살뜰히 챙기게.",
   "10": "챙 넓은 삿갓을 눌러쓴 듯 앞이 잘 안 보이는 달이야. 이득을 보려면 동쪽을 향하되 시작을 신중히 하게. 사람을 가볍게 사귀면 손해가 닥치니 새 인연은 천천히 알아 가게. 서두르지 않고 살피면 길이 보이네.",
   "11": "애쓴 만큼 공이 드러나지 않는 달이야. 바른 마음으로 제 자리를 지키고 몸가짐을 조심하면 어수선한 흐름이 좋게 바뀌네. 동지 무렵에는 불과 물 단속을 꼼꼼히 하게. 몸을 낮추는 것이 곧 힘일세.",
   "12": "귀한 사람이 바로 곁에 있어 돈과 이득을 보는 달일세. 먹을 복이 넉넉하고 쌓였던 외로움도 풀리네. 곁의 사람에게 고맙다고 말하면 그 복이 더 오래 가네. 한 해를 마무리하는 인사도 미리 챙겨 두게."
  }
