   "12": "도와주겠다는 사람이 있어도 말뿐일 수 있으니 너무 기대지 말게. 경솔하게 움직이면 뜻밖의 방해가 끼네. 매사를 차분히 처리하면 끝내 좋은 결과가 오니 조급해하지 말고 한 걸음씩 가게."
