  "sum": "올해는 애쓰는 곳과 얻을 곳이 어긋나기 쉬우니 욕심을 덜고 마음의 중심을 잡으면 한결 가벼워지는 해일세. 음력 5월과 9월에 숨통이 트이고 12월은 집안이 편안하니 그때까지 차분히 준비하며 기다리게.",
  "image": "옛 풀이에서는 이 괘를 '나무 위에서 물고기를 찾아 헤매는 모습'이라 하네. 물고기는 물에 있는데 나무 위에서 찾으면 헛수고가 되니, 애쓰는 자리와 얻을 자리를 잘 맞춰야 한다는 뜻이야.",
  "chongun": "올해는 욕심을 덜고 중심을 잡을수록 마음이 가벼워지는 해일세. 애쓴 곳과 얻을 곳이 어긋나기 쉬우니 움직이기 전에 어디서 얻을지부터 헤아려 보게. 중간에 발이 멈추기도 하고 사람을 만났다가 금세 헤어지기도 하니 마음이 한곳에 머물도록 다잡게. 제 몫을 넘는 일은 손대지 말고 밖에서 이득을 좇다 삐끗하지 않게 조심하게. 눈앞의 급한 불만 끄다 보면 큰 것을 놓치기 쉬우니 중요한 일부터 챙기게. 억지로 얻으려 하면 서로 마음만 상하니 재료와 때가 갖춰질 때까지 준비하며 기다리게. 음력 5월과 9월에는 숨통이 트이고 12월에는 집안이 평안하네. 음력 1월과 2월, 7월과 8월은 몸을 낮추고 조용히 지내게.",
  "money": "돈은 눈앞의 이득에 덥석 손대지 않는 게 좋은 해일세. 돈 흐름이 비치는 듯해도 처음만 반짝할 수 있으니 큰 액수는 바라지 말고 작은 저축부터 쌓게. 음력 5월과 9월에는 뜻밖의 돈이 들어올 수 있네.",
  "work": "일은 새로 벌이기보다 지금 하는 일을 지키는 쪽이 낫네. 제 몫을 넘는 일은 손대지 말고 재료와 때가 갖춰질 때까지 준비하게. 음력 5월에는 미뤄 둔 일을 꺼내 움직여 보게.",
  "love": "사람 사이는 억지로 붙잡으면 서로 마음만 상하니 한 걸음 물러서 지켜보게. 곁에 엉뚱한 사람을 들이기보다 오래 알고 지낸 사람을 아끼게. 음력 9월에는 새 식구나 곁에 사람이 늘어나는 기쁨이 있네.",
  "health": "몸은 마음이 흔들리면 함께 흔들리니 잠과 끼니를 일정하게 지키게. 음력 8월에는 몸이 무거울 수 있으니 쉬어 가게. 몸이 계속 불편하면 병원에 먼저 가 보게.",
  "tips": [
   "할 일 목록에서 급해 보이지만 중요하지 않은 일 하나를 지우게.",
   "돈이 될 것 같은 제안은 그 자리에서 정하지 말고 하룻밤 두고 살피게.",
   "억지로 붙잡지 말고 재료와 때가 갖춰졌는지 한 번 더 살피게."
  ],
  "flow": "ccocgoocgogg",
  "months": {
   "1": "뜻하지 않은 걸림돌이 갑자기 앞을 막는 달일세. 다음 달까지는 새 사업을 벌이지 말게. 돈 흐름이 비치는 듯해도 처음만 반짝하고 뒤로 갈수록 힘이 빠지니 눈앞의 이득에 덥석 손대지 말게.",
   "2": "집안 분위기가 들썩여 이사가 어렵다면 먼 걸음이라도 한 번 다녀와야 걱정이 가벼워지는 달일세. 봄에는 돈 흐름이 뜻대로 안 되니 욕심을 덜게. 일을 마무리할 때는 남의 말을 그대로 믿지 말고 저녁 약속은 줄이게.",
   "3": "제때 시작하지 못한 일의 결실이 막막하게 느껴지는 달이야. 아픈 사람이 있는 집은 잠시 걸음을 줄이게. 돈 흐름은 있으나 급히 잡으려 하면 달아나니 기다렸다가 거두게. 서두르는 마음이 이달의 걸림돌일세.",
   "4": "기다리는 결실이 아직 보이지 않는 달일세. 큰돈을 바라지 말게. 새 일을 꾸며도 사람 사이가 매끄럽지 않으니 지금 가진 것을 지키게. 새로 얻을 때는 따로 있다고 여기게.",
   "5": "그동안 힘겹던 일에 숨통이 트이며 다시 살아나는 달이야. 일을 계획하면 뜻대로 되고 뜻밖의 수입도 있네. 집안이 화목하니 이때 움직이지 않으면 언제 움직이겠나. 미뤄 둔 일을 꺼내 보게.",
   "6": "처음엔 힘들다가 뒤로 갈수록 풀리는 달일세. 좋고 나쁨이 또렷하지 않아 판단이 흐려질 수 있으니 신중하게 살피게. 먼 걸음은 손해가 되기 쉽고 집 안에 머물면 마음이 편하니 새 일은 벌이지 말고 하던 일을 이어 가게. 흐린 날은 곧 개네.",
   "7": "돈이 새는 것을 막아 두지 않으면 관청 일이나 뒷말이 생길 수 있는 달일세. 자리를 옮기거나 하던 방식을 잠시 바꿔 보는 것도 방법이네. 돈 흐름이 있을 때 잘 모아 두게. 뒤로 갈수록 힘이 빠지니 이달은 조용히 지내게.",
   "8": "가깝던 사람과 거리가 생기거나 식구가 멀리 떠나 섭섭한 달일세. 몸이 무거우면 쉬어 가고 이달은 마음을 가라앉혀 크게 움직이지 말게. 조용히 지내다 보면 이 마음도 곧 지나가네. 안부 전화를 한 통 걸어 보게.",
   "9": "새 식구가 생기거나 곁에 사람이 늘어나는 기운이 있는 달일세. 돈 흐름도 좋아 뜻밖의 돈이 들어오네. 늦게 찾아온 만큼 더 값지게 느껴지는 때이니 그 기쁨을 식구와 함께 누리게.",
   "10": "동쪽과 북쪽은 이롭지 않으니 일을 시작하기 전후를 조심하게. 먼 걸음보다 집 안이 편한 달이야. 일을 벌이기보다 하던 일을 지키게. 이득은 서쪽 방향에서 보이니 문밖 일은 다음 달로 넘기게.",
   "11": "일을 마무리한 뒤 북쪽에서 돈이 생기는 달일세. 몸이 편안하니 바깥의 어수선한 일에 쉽게 휘둘리지 않네. 다만 곁에 엉뚱한 사람을 들이면 곤란해질 수 있으니 새로 만나는 사람과는 거리를 두게.",
   "12": "몸도 돈 흐름도 기운차 집안이 태평한 달일세. 그렇다고 새 판을 벌이면 기쁨이 줄어드니 참게. 도와주는 사람이 있어 뜻밖에 일이 되니 서둘러 벌이기보다 기다리며 거두게. 도와준 사람에게 고마움을 전하게."
  }
