   "4": "달콤한 말에 솔깃하다가 잔꾀에 넘어가기 쉬운 달이야. 헛된 이름을 좇다 마음만 다치네. 미리 대비해 두면 굴러온 어려움이 오히려 도움으로 바뀌니 경계를 늦추지 말게. 집을 떠나고 싶은 마음은 잠시 눌러 두게.",
   "5": "돈을 원하면 정성을 다해 구하게. 다 얻지는 못해도 들인 정성만큼은 돌아오네. 동쪽에서 도와주는 사람이 우연히 나타나니, 새 일에 손댈 때 신중히 살피면 작더라도 이득이 남네.",
   "6": "기운이 잘 맞아 바라던 일이 드디어 이루어지는 달일세. 남과 힘을 합치면 살림을 불릴 수 있네. 몸도 돈 흐름도 좋으니 사람을 만나 일을 의논하는 걸 망설이지 말게. 첫걸음을 가볍게 떼어 보게.",
   "7": "복이 길게 이어져 하는 일이 줄줄이 풀리는 달이야. 자리가 오르지 않는다면 자식 쪽에 기쁜 일이 있네. 아침저녁으로 마음이 즐거우니 가족과 가까운 곳으로 나들이를 다녀오게.",
   "8": "남과 함께 꾀하는 일이 처음엔 좋아 보여도 뒤에 틀어질 수 있으니 조심하는 달일세. 제 몫을 지키는 게 가장 좋네. 새 일을 찾아 이리저리 뛰어도 남는 게 없으니 이달은 발걸음을 아끼고 혼자 조용히 가게.",
   "9": "벌인 일이 시작만 있고 끝이 흐지부지될 수 있는 달이야. 남의 이익에 끼어들면 곤란해지네. 도와줄 사람은 서쪽과 북쪽에서 오니 일을 매듭짓는 과정과 그다음을 신중히 챙기게.",
   "10": "가려고 벼르는데 발이 안 떨어져 속만 끓는 달일세. 이성 문제에 마음이 기울면 손해를 보네. 이득은 서쪽과 북쪽에서 오니 벌여 둔 일을 과감히 마무리하면 그다음에 돌아오네.",
   "11": "돈이 생겨도 남의 시샘을 사기 쉬운 달일세. 동쪽은 이롭지 않고 서쪽이 좋으니 새 일에 힘을 쏟기보다 하던 일을 잘 마무리하게. 좋은 사람을 곁에 두면 그 덕을 크게 보네. 자랑은 속으로만 하게.",
   "12": "조용한 곳에서 마음을 다잡고 빌면 힘든 고비를 넘길 수 있는 달일세. 남과 일을 꾀하려면 먼저 그 사람 속을 깊이 헤아리게. 갈피를 못 잡기 쉬우니 방향부터 정하고 움직이게."
