   "5": "한 번 다투기 쉬운 달일세. 동쪽과 남쪽에는 가지 말게. 일에 끼어들었다가 언성이 높아질 수 있네. 남을 이해하려 애써도 말다툼은 생기니 이해를 구하기 전에 자리를 피하게.",
   "6": "나아갈지 물러설지 가늠이 안 되는 달이야. 가까운 사람을 믿어야 할지 헷갈리네. 잘못 믿으면 손해가 크니 돈 거래는 미루게. 동쪽과 서쪽 길에는 자네 뒤를 노리는 사람이 있으니 그쪽 길은 줄이게.",
