   "8": "오랜 기다림 끝에 막혔던 일이 풀려 반가운 달이야. 믿음 없이 손을 잡으면 손해가 나니 재산 단속을 잘하게. 몸은 거뜬하고 저축도 차오르니 사람 관계만 조심하면 집안이 태평하네.",
   "9": "동쪽과 남쪽은 이롭지 않으니 발길을 돌리게. 크게 벌이기보다 작게 시작하는 편이 마음이 편하네. 뜻밖의 돈이 들어오니 조급해하지 말고, 남과 힘을 합치면 제법 쏠쏠한 이득이 남네.",
   "10": "돈도 몸도 튼튼해 바라던 일이 이루어지는 달일세. 가끔 말이 붙으니 조심하게. 결실까지는 시간이 좀 걸리니 분수를 지키며 편히 있으면 이득이 그 안에 있고, 과하게 움직이면 복이 깎이네. 서두르지 말고 한 걸음씩 가게.",
   "11": "온화한 기운이 집 안에 가득한 달이야. 뜻밖의 수입이 아니더라도 집안에 기쁜 일이 들어오네. 식구끼리 정이 깊어져 집 안이 따뜻하니 좋은 일이 생겨도 서로 섭섭하지 않게 공을 나누게.",
