   "2": "운이 고르지 못해 걱정이 쌓이기 쉬운 달이야. 마음이 심란하다고 남의 일에 끼어들면 뒷말이 돌기 쉬우니 조심하게. 걱정이 머물 땐 산책이나 새 취미로 기분을 돌리고 남의 다툼에는 귀만 열어 두게.",
   "3": "마음이 흔들려 갈피를 잡기 어려운 달이야. 마음이 흔들리니 벌이는 일도 허술해지기 쉽네. 집 안을 미리 정돈하고 해야 할 일 목록을 적어 두면 어려움을 비껴갈 수 있네.",
   "4": "도와줄 사람이 집으로 찾아오는 달일세. 남쪽과 북쪽에 좋은 기운이 있으니 혼자 하지 말고 여럿이 함께 일을 벌여 보게. 작은 것이 모여 큰 것이 되니 벌이가 넉넉해지네.",
   "5": "가는 곳마다 돈 벌 기회가 눈에 띄고 좋은 일이 따라붙는 달이야. 얼굴에 웃음이 번지고 하는 일이 두루 이뤄지네. 먹을거리나 손으로 만드는 일에서 이득이 나니 그쪽 기회를 눈여겨보게.",
