   "7": "운이 막히는 듯해 집안 걱정이 생기기 쉬운 달이야. 들어온 돈이 반만 남으니 처음은 좋아도 끝이 흐려지기 쉽네. 오래 찾아뵙지 못한 어른 댁이나 조상 산소에 안부를 전하면 마음이 한결 가벼워지네.",
   "8": "마음이 이유 없이 불안한 달이지만 두 사람 마음이 한결같아 돈이 날마다 조금씩 붙네. 다만 들어온 돈이 쉽게 흘러 나가니 들어오는 대로 저금통에 나눠 담게. 함께하는 사람의 마음을 믿고 하던 일을 이어 가게.",
   "9": "먼 곳에서 반가운 소식이 날아오는 달이야. 옛 벗을 만나거나 그리운 얼굴을 보게 되네. 그 자리에서 남의 말다툼에 끼면 뒷말이 따르니 즐거운 이야기만 나누고 자리를 일찍 파하게.",
