   "5": "사는 곳에 변화가 생겨 이사나 새 집을 알아보면 답답하던 일이 좋은 쪽으로 풀리는 달이야. 다만 서둘러 덤비면 일이 꼬이기 쉽고 가게 일을 섣불리 늘리면 힘에 부치네. 집을 볼 때는 두세 곳을 비교한 뒤에 결정하게.",
