   "7": "앉아 있어도 마음이 불안한 달이야. 남쪽과 북쪽은 좋고 동쪽과 서쪽은 막혔으니 그쪽 걸음은 줄이게. 될 듯하다가 어긋나는 일이 있으니 새 일보다 하던 일을 알차게 다지는 데 힘을 모으게. 흔들릴수록 뿌리를 다지게.",
