   "5": "남쪽 걸음을 줄여야 하는 달이야. 일을 너무 벌이면 불리하네. 도와주는 사람을 만나면 뜻밖의 돈이 오니 사람을 사귈 때 정성을 들이게. 다만 손해가 스칠 수 있으니 셈은 꼼꼼히 하게. 인연을 가려 사귀는 게 요령일세.",
   "6": "서쪽으로 가면 좋던 일도 어긋나기 쉬운 달일세. 서둘러 마무리하려 들기보다 한 걸음씩 가는 게 든든하네. 시작만 요란하고 끝이 흐지부지할 수 있으니 이번 달엔 속도를 늦추고 기다리게. 기다림도 일의 한 부분일세.",
   "7": "매사를 조심해야 하는 달이야. 손해가 뒤따를 수 있고 올해 가장 조심할 것은 술이네. 동북쪽 사람과 어울리면 말다툼이 붙으니 일을 시작하자는 의논이 오면 한 번 더 따져 보게. 잔을 덜어 내면 걱정도 덜어지네.",
   "8": "하고 싶은 일은 많은데 힘이 따라 주지 않는 달일세. 하는 일이 허공에 뜬 듯해 앞으로 가지도 멈추지도 못하네. 얕은 꾀를 부리지 말고 할 수 있는 작은 일부터 차근차근 하게. 서두르지 않는 사람에게 힘이 붙네.",
   "9": "마음에 걱정이 가득해 집에 머무는 게 나은 달이야. 밖으로 나서거나 일을 벌이지 말게. 다툼을 벌이면 뒷말이 따르니 말을 아끼게. 돈은 들어와도 모으기 어려우니 들어온 날 바로 저축 몫을 떼어 두게.",
