   "5": "동북쪽 방향에서 벌이가 생기는 달이야. 괜히 자리를 옮기면 손해지만 새 일을 계획하는 것은 이롭네. 일을 시작하기 전에 때를 잘 살피고 준비하면 큰돈이 뒤따르네.",
   "6": "분위기가 확 바뀌어 딴 세상을 만난 기분이 드는 달일세. 돈이 아니더라도 아이들 일로 기쁨이 찾아오네. 처음엔 어려워 보이던 일이 뒤에 좋게 돌아서니 조급해하지 말게.",
