   "5": "뜻밖의 변수가 생길 수 있으니 행동을 조심하는 달일세. 마음을 다치게 할 사람은 가려 사귀지 못한 인연일 테니 그 사람과는 일을 함께 꾸미지 말게. 새 일을 시작하면 어긋나기 쉬우니 하던 일만 붙들고 조용히 지내게.",
   "6": "일마다 걸림돌이 있어 마음이 어지러운 달이야. 돈이 샐 수 있으니 자동이체나 구독료처럼 새는 구멍을 미리 막아 두게. 그래도 달 끝 무렵에는 막혔던 곳에 봄이 돌아오듯 한 줄기 빛이 비치네.",
   "7": "메마른 들판에 비가 쏟아지듯 답답하던 일이 풀려 여물어 가는 달일세. 도와주는 사람이 와서 손을 보태니 기쁜 소식이 이어지네. 밖의 돈을 탐내지 않으면 얻은 것을 온전히 지킬 수 있으니 욕심을 덜게.",
