   "6": "기다리는 시간이 길어 마음이 지치는 달일세. 배를 타거나 물놀이를 가는 일은 이번엔 접어 두게. 새로 사귄 사람이 달콤한 말을 하면 한 번 더 따져 보게. 기다린 만큼 속이 단단해지니 조바심은 내려놓고 하던 일을 꾸준히 이어 가게.",
   "7": "뜻밖에 남의 도움이 내 집 문턱까지 찾아오는 달일세. 오래 참고 견딘 덕이니 반갑게 받게. 누군가 함께 해 보자고 하면 조건부터 차분히 들어 보게. 집 안을 말끔히 치우면 마음도 가라앉고, 받은 도움에는 작은 답례라도 챙겨 두게.",
