   "5": "집안에서 아랫사람이 윗사람을 앞지르려 해 분위기가 편치 않은 달이야. 서두르면 될 일도 꼬이지만 천천히 다가가면 밝게 풀리니 급한 결정은 한 주쯤 묵혀 두게. 돈이 샐 틈도 막아 두게. 아랫사람과는 마주 앉아 차분히 속이야기를 들어 주게.",
   "6": "마음은 있는데 풀어 갈 방법이 떠오르지 않아 답답한 달일세. 그래도 운이 조금씩 돌아오니 살림을 편히 꾸릴 기회가 보이네. 손에 잡히지 않는 돈을 좇다가는 손해가 크니 눈앞의 일만 챙기게. 작은 일부터 하나씩 끝내면 자신감이 돌아오네.",
   "7": "일이 마음에 차지 않아 속이 끓는 달이야. 애쓴 만큼 알아주지 않아 서운하고 집안에 몸이 불편한 식구도 있어 걱정이 겹치네. 그래도 조급해하지 말고 하루 한 가지씩만 해내게. 저녁마다 오늘 해낸 일을 하나씩 적어 보게.",
   "8": "말다툼에 휘말리면 관청 일까지 번져 벗어나기 어려운 달일세. 집안 어른들 안색도 한 번씩 살펴 드리게. 돈 걱정이 덜한 대신 아이들 쪽에 마음 쓸 일이 생길 수 있으니 안부를 챙기게. 관청 서류는 기한을 넘기지 않게 미리 챙겨 두게.",
   "9": "관청 일이 문 앞까지 와 집안이 어수선한 달이야. 말과 서류를 특히 조심하게. 집을 지키는 편이 좋지만, 밖에서 만나는 사람에게 속마음을 다 털어놓지는 말게. 도장과 통장은 식구 말고는 손대지 못하게 잘 챙겨 두게.",
   "10": "오랜만에 숨통이 트이는 달일세. 가는 곳마다 벌이가 생기니 이때 힘껏 움직이게. 움직이지 않으면 집안 분위기가 흔들릴 수 있으니 게으름은 경계하게. 벌이가 생기면 작은 몫이라도 떼어 비상금으로 묶어 두게.",
