   "12": "밖에서 돈을 구해 봐야 남는 게 적은 달일세. 성심껏 일한 만큼만 작은 이익이 오니 대가 이상을 바라지 말게. 이사나 자리 옮김을 생각해 왔다면 이달에 알아보게. 새해 계획은 크게 잡지 말고 지킬 수 있는 만큼만 세우게."
