   "2": "반가운 소식이 드는 달일세. 이익은 서쪽에 있으니 마무리할 때를 잘 잡게. 다만 이성 문제로 입방아에 오르기 쉬우니 행동을 단정히 하게. 향기 좋은 꽃 한 다발을 식탁에 두면 집안 분위기도 밝아지네.",
