   "4": "관공서 쪽 일이 어수선한 달일세. 거래에서 손해만 눈에 띄어 배신감에 속이 쓰릴 수 있네. 남쪽으로 가면 하던 일마저 틀어지니 이번 달에는 발길을 돌리게. 섭섭한 거래는 따지기보다 기록으로 남겨 두게. 감정이 가라앉은 뒤에 다시 보면 길이 보이네.",
   "5": "식구와 살 곳이 늘어 집안이 즐거운 달이야. 살림이 넉넉해지고 마음도 편안하네. 다만 남 때문에 손해를 볼 수 있으니 달콤한 말은 한 번 더 따져 보게. 기쁜 일이 있을 때일수록 말을 아끼고 식구들과 조용히 누리게.",
   "6": "일은 많은데 손에 남는 것이 적어 허탈한 달일세. 기대를 낮추고 해야 할 일 목록을 절반으로 줄이게. 그래야 버틸 힘이 남네. 지친 몸은 충분한 잠으로 달래 주게. 이런 때는 몸을 아끼는 것이 가장 큰 밑천이네.",
   "7": "그간의 수고와 참고 견딘 시간이 드디어 빛을 보는 달이야. 바라던 일이 이뤄지고 살림이 다시 일어나네. 서류에 도장 찍을 때만 꼼꼼히 확인하게. 공을 인정받으면 도와준 사람들의 이름도 함께 불러 주게.",
   "8": "힘든 가운데 좋은 기운이 끼어 처음은 고되고 뒤로 갈수록 나아지는 달일세. 남과 다투면 곤란해지니 참게. 길 잃은 나그네처럼 속이 어지러울 땐 일찍 쉬게. 하루를 마칠 땐 잘한 일 하나를 떠올리며 잠들게.",
