   "11": "멀리 가면 어려움을 만나기 쉬운 달이야. 도둑이 들 수 있으니 문단속을 단단히 하게. 제 몫을 벗어나 움직이면 뜻밖의 껄끄러운 사람을 만나니 신중하게 행동하게. 밤늦은 귀가는 줄이고 창문 잠금도 한 번 더 확인하게. 작은 방심이 큰 손해를 부르는 때야.",
   "12": "좋은 흐름이 꾸준하지 않아 세상일이 힘겹게 느껴지는 달일세. 애써도 돈이 쉽게 오지 않네. 그래도 남쪽에는 좋은 기운이 있으니 그쪽으로 뜻을 펴 보게. 연말에는 한 해 고생한 스스로에게 작은 상을 주게."
