  "chongun": "올해는 하는 일마다 잘 풀리고 살림이 차츰 불어나는 해일세. 돈도 들어오고 주변에서 자네 이름을 알아보는 일도 늘겠네. 집안에서는 식구들이 모여 웃을 일이 많고, 이사를 고민했다면 올해가 좋은 때야. 처음 몇 달은 조금 고단해도 시간이 갈수록 복이 커지네. 품고 있던 계획을 시작하고 뜻을 펼치기에 딱 좋은 때일세. 다만 음력 5월에는 가까운 사람 때문에 손해를 볼 수 있고, 음력 7·8월에는 남쪽으로 멀리 다니는 일을 줄이는 게 좋네. 넉넉할 때 조금씩 모아 두면 복이 오래 가네.",
  "money": "돈은 하는 일에 따라 자연스럽게 들어오고 뜻밖의 수입도 생기는 해일세. 잘 벌리는 때일수록 월급날 저축부터 먼저 떼어 두면 올해 복이 오래 남네. 작은 손해에 마음 상하지 않는 여유도 필요하네.",
