   "3": "집안이 두루 편안하고 서쪽으로 볼일을 보면 이익이 따르는 달일세. 다만 사소한 일로 돈이 새기 쉬우니 작은 손해에 마음 상하지 말게. 가계부를 가볍게 적어 보면 도움이 되네.",
