   "2": "친한 사람이라고 다 믿지 말게. 정성껏 베풀어도 서운함만 돌아올 수 있는 달이야. 이사나 자리 옮기기도 좋지 않으니 지금 자리에서 혼자 조용히 할 일을 챙기는 편이 낫네. 괜한 호의로 지갑을 열지 말게.",
   "3": "몸이 쉽게 지치는 달일세. 달콤한 제안에 속기 쉬우니 솔깃한 이야기는 흘려듣게. 남의 말만 믿고 서명하면 관청 일로 번질 수 있으니 서류는 꼼꼼히 읽고 도장을 찍게.",
   "4": "모든 일에 몸을 사려야 하는 달이야. 감당하기 힘든 일이 몰려올 수 있으니 괜히 길을 나서지 말고 운전도 조심하게. 힘들다고 한탄만 하지 말고 고생 뒤에 좋은 날이 온다는 걸 떠올리게.",
   "5": "꾀하는 일은 많은데 딱 들어맞는 게 없어 답답한 달일세. 이치에 맞지 않는 일이 생겨도 억지로 밀지 말게. 배우자와 사이가 서먹해질 수 있으니 먼저 따뜻한 말 한마디를 건네게.",
   "6": "술자리와 모임에 끌려다니기 쉬운 달이야. 가까운 사람 말만 믿고 따라갔다가 후회할 수 있으니 저녁 약속은 줄이게. 누가 솔깃한 얘기를 꺼내면 하룻밤 자고 나서 답하게.",
   "7": "가까운 곳에서 애써 구하면 조금씩 길이 트여 작은 보탬을 손에 쥘 수 있는 달일세. 먼 곳으로 떠나면 얻는 것보다 잃는 것이 많으니 먼 원정은 접어 두게. 멀리 보지 말고 가까운 데서 차근차근 구하게.",
   "8": "집안에 결혼 이야기가 오가거나 식구가 느는 기쁜 일이 있을 수 있는 달이야. 수고는 많아도 보람이 남는 때일세. 술자리나 연애 문제에 휩쓸리면 돈과 이름을 함께 놓칠 수 있으니 마음을 흐트러뜨리지 말게.",
   "9": "일이 안 풀리는데 몸까지 지치기 쉬운 달일세. 몸이 무거우면 쉬어 가고 마음을 모아 정성을 들이면 다가오는 어려움을 막을 수 있네. 이달에는 잠과 끼니를 무엇보다 먼저 챙기고 저녁 약속은 되도록 줄이게.",
   "10": "부부 사이가 삐걱거려 집 안 분위기가 편치 않은 달이야. 엉뚱한 데서 답을 찾느라 우왕좌왕하기 쉬우니 먼저 말을 끝까지 들어 주게. 동쪽에 사는 가까운 사람과는 돈이 얽힌 약속을 하지 말게.",
   "11": "애는 쓰는데 결과가 조금 늦게 돌아오는 달일세. 이리저리 뛰어다녀도 고단하기만 하니 일을 넓히지 말게. 운을 탓하기보다 내 분수 안에서 할 일에 충실하면 좋은 시절이 돌아오네.",
   "12": "머물 곳도 마땅찮은 듯 외로움이 밀려오는 달이야. 가까운 사람을 믿었다가 서운함을 겪을 수 있으니 속내는 아껴 두게. 올해를 잘 버틴 자신에게 따뜻한 밥 한 그릇을 대접하게."
