   "5": "옳고 그름을 따지는 자리에 끼면 뒷말을 피하기 어려운 달일세. 새 일을 벌이거나 하던 일을 크게 늘리면 어려워지니 지금 하던 일을 지키는 데 힘쓰게. 마음이 불안하면 조용히 정성을 들이며 마음을 다잡게.",
   "6": "막히는 일이 많아 한숨이 늘기 쉬운 달이야. 앞이 잘 보이지 않는 듯해도 억지를 부리지 말고 순리대로 한 걸음씩 옮기게. 안개는 해가 뜨면 걷히는 법이니 곧 갈 길이 보이네.",
   "7": "집안 분위기가 들썩이는 달일세. 정성을 들이면 어려움을 비켜 가지만 그렇지 않으면 돈이 새기 쉽네. 말다툼이 붙으면 작은 일이 관청까지 번질 수 있으니 억울해도 한 번 삼키고 신중하게 움직이게.",
