   "9": "밖에서 활발히 움직이면 구하는 만큼 거둘 수 있는 달일세. 서류로 돈을 얻고 글재주에도 빛이 들어 이름이 높아지네. 받은 만큼 인정을 베풀면 복이 더 오래 머무니 주변 사람을 챙기게.",
   "10": "높은 곳에 한가로이 앉아 스스로의 성취를 즐기는 달이야. 걱정이 없고 꾀하는 일마다 이뤄져 가만히 앉아서도 돈이 들어오네. 바른 도리를 소홀히 하면 돈이 새어 나갈 수 있으니 베푸는 마음을 잊지 말게.",
