   "12": "새 힘이 차오르며 만물이 새 기운을 머금는 달이야. 도와줄 사람을 만날 운이니 혼자보다 함께 일하는 게 좋네. 집안이 화평하고 자녀에게 기쁨이 여무니 사랑으로 식구들을 대하게."
