   "4": "오랜 가뭄처럼 답답한 기운이 이어지는 달이야. 배우자와 아이들 쪽에 걱정이 생기고 말이 무성해지기 쉽네. 잎이 말랐다고 나무를 베지는 않는 법이니 식구들을 다독이며 말을 아끼게.",
