   "12": "움직일 기운이 들어 한 번은 먼 길을 나설 달이야. 처음엔 고단해도 뒤에는 일이 잘 풀려 참아 온 날들이 값지게 보이네. 서둘러 덤비면 후회하니 새 일은 한 박자 쉬고 시작하게. 짐은 가볍게 꾸리게."
