  "sum": "올해는 힘이 부족해서가 아니라 때가 덜 익었을 뿐이니, 서두르지 않고 작은 일을 정성껏 이어 가는 사람이 이기는 해일세. 음력 8월과 10월에 좋은 흐름이 오니, 그때까지 몸과 실력을 다져 두게.",
  "image": "옛 풀이에서는 이 괘를 '여의주를 아직 못 쥔 용이 때를 기다리는 모습'이라 하네. 힘은 충분한데 때가 아직 덜 익었을 뿐이니, 기다리며 준비하면 곧 하늘로 오른다는 뜻이야.",
  "chongun": "올해는 때가 덜 익어서 일이 더디게 느껴지는 해일세. 서두르지 말고 버티는 쪽이 이기니, 일하다 막히는 순간이 와도 끝내는 모양이 잡히네. 중간에는 어깨가 펴지는 때도 있고 뜻밖의 도와주는 사람 덕에 이름이 알려지기도 하네. 하던 일이 흐지부지되면 서류 문제나 말다툼으로 이어지기 쉬우니 손 놓지 말고 끝까지 마무리하게. 아끼는 사람과는 작은 일로 서운함이 쌓일 수 있으니 말을 한 번 더 고르게. 음력 8월과 10월에 좋은 흐름이 오고, 음력 1월·5월·6월·9월·11월에는 몸을 낮추고 차분히 지내게. 기다리는 동안 몸과 실력을 다져 두면 때가 왔을 때 단번에 뛰어오를 수 있네.",
  "money": "큰돈을 벌기보다 가진 것을 지키고 새는 돈을 막는 쪽이 이로운 해일세. 달콤한 말로 다가오는 제안이나 동업 이야기는 하룻밤 묵혀 두고 따져 보게. 음력 9월에는 지갑을 단단히 여미고 일정을 줄여 돈이 새지 않게 하게.",
  "work": "지금 붙든 일 하나에 힘을 모아 끝까지 마무리하는 해일세. 마음이 들떠 여러 일을 벌이면 흐지부지되기 쉬우니 하나씩 끝내 가게. 음력 3월에는 집이나 자리를 바꾸면 길이 트이고, 음력 10월에는 남의 도움으로 일이 이뤄지네.",
  "love": "아끼는 사람과는 작은 일로 서운함이 쌓이기 쉬우니 말을 한 번 더 골라 하게. 음력 9월에는 식구들 사이에 말이 날카로워지기 쉬우니 짧고 부드럽게 말하게. 새로 사귀는 사람은 겉만 보지 말고 한동안 지켜본 뒤에 마음을 열게.",
  "health": "서두르지 않고 지내면 몸도 마음도 든든한 해일세. 마음이 뒤숭숭한 날은 집에만 있지 말고 가까운 길을 걸으며 머리를 식히고, 음력 3월에는 물가 나들이나 배 타는 일을 미루게. 몸이 계속 불편하면 병원에 먼저 가 보게.",
  "tips": [
   "오늘 미뤄 둔 작은 일 하나를 골라 끝까지 마무리하게.",
   "달콤한 제안이나 돈 이야기는 하룻밤 자고 다시 따져 보게.",
   "아끼는 사람에게 할 말은 한 번 더 고른 뒤에 건네게."
  ],
  "flow": "cogoccogcgco",
  "months": {
   "1": "아직 해가 덜 뜬 새벽처럼 조용히 준비하는 달일세. 새 일을 벌이면 틀어지기 쉬우니 준비만 해 두게. 동쪽으로 움직이는 일은 줄이고, 달콤한 말로 다가오는 제안은 하룻밤 자고 나서 다시 따져 보게. 급할수록 돌아가는 달이야.",
   "2": "기회를 잡으려 애써도 손끝에서 자꾸 빠져나가는 듯한 달이야. 그래도 중순이 지나면 뜻밖의 도움이 닿아 일이 풀리기 시작하네. 요령 피우지 말고 들인 정성만큼 거둔다고 믿고 꾸준히 손을 놀리게.",
   "3": "집을 옮기거나 자리를 바꾸면 길이 트이는 달일세. 다만 물가 나들이나 배 타는 일은 이번에는 미뤄 두게. 사람을 사귈 때도 겉만 보지 말고 한동안 지켜본 뒤에 마음을 열면 든든하네.",
   "4": "일이 곧 될 듯 보여도 아직 조금 더 익어야 하는 달이야. 참을 수 있는 데까지 참는 것이 이달의 공부일세. 성급히 결론을 내지 말고 한 발 물러서 있으면 쌓인 인내가 나중에 어려움을 막아 주네. 기다림도 일이라 여기게.",
   "5": "달이 구름에 가린 듯 앞이 잘 보이지 않는 달일세. 남을 밀치고 얻은 이익은 오히려 발목을 잡으니 쉬운 길에 눈 돌리지 말게. 이성 문제로 마음이 흔들릴 수 있으니 술자리는 일찍 일어서고 매사 한 걸음 더 조심하게.",
   "6": "가까이 다가오는 사람 가운데 손해를 끼칠 사람이 섞여 있을 수 있는 달이야. 동업이나 공동 작업은 상대를 잘 가려야 마음이 편하네. 마음이 들떠 여러 일을 벌이지 말고 지금 붙든 일 하나에만 힘을 모으게.",
   "7": "욕심은 나는데 손에 쥔 밑천이 모자라 애만 쓰기 쉬운 달일세. 집에 있으면 마음이 뒤숭숭하니 밖으로 나가 산책하며 머리를 식히게. 곁에 달라붙는 사람이 누구인지 눈여겨보게.",
   "8": "드디어 볕이 드는 달일세. 오래 기다린 좋은 소식이 오거나 결혼 이야기가 오갈 수 있네. 살림도 몸도 기운이 붙으니 미뤄 둔 계획을 꺼내 한 걸음 내디뎌 보게. 기쁜 일은 식구와 함께 나누게.",
   "9": "식구들 사이에 말이 날카로워지기 쉬운 달이야. 아이와 관련된 기쁜 소식이 있어도 그 일로 돈이 나갈 수 있으니 지갑을 단단히 여미게. 여기저기 뛰어다녀도 남는 것이 적으니 일정을 반으로 줄이게.",
   "10": "남의 손을 빌려 일이 이뤄지고 이름도 알려지는 달이야. 마음이 여유로워 쉬어 가기에도 좋네. 다만 새로 엮이는 사람 때문에 손해를 볼 수 있으니 돈 이야기가 나오면 한 박자 쉬고 대답하게.",
   "11": "계획 없이 흘러가다 보니 일이 어긋나기 쉬운 달일세. 집안에 잔걱정이 생겨 마음이 불편할 수 있네. 나아갈 때와 물러설 때를 가늠하도록 이번 주에 할 일을 적어 두고 하나씩 지워 나가게.",
   "12": "괜히 세상일에 뛰어들지 말고 가진 것을 지키는 달일세. 말다툼이 붙을 자리에 끼면 일이 커지니 한 번만 참고 넘기게. 그 고비만 넘기면 새해부터 막혔던 일이 풀리기 시작하네."
  }
