   "4": "부부와 연인 사이가 부드럽고 집안 분위기가 든든해 어려운 일이 저절로 물러가는 달이야. 돈 복이 동쪽에 있으니 볼일이 있으면 그쪽으로 발걸음을 옮겨 보게. 좋은 흐름을 믿고 부지런히 움직이게.",
   "5": "봄 꽃밭에 벌과 나비가 모여들듯 사람과 좋은 소식이 모이는 달일세. 이성과의 인연이 따뜻하게 이어지고 뜻밖의 성과로 이름이 나기도 하네. 이 기세가 다음 달까지 이어지니 망설이던 일을 이번 달 안에 시작하게.",
   "6": "집안이 화목해서 복이 제 발로 들어오는 달이야. 새로운 일에 손대면 이익이 붙고 동쪽에서 뜻밖의 수입도 생기네. 서쪽과 남쪽 길도 이로우니 미뤄 둔 출장이나 방문을 이번에 다녀오게.",
   "7": "서쪽에서 온 사람과 돈을 엮으면 잃기 쉬운 달일세. 사람을 가려 사귀면 손해를 피할 수 있네. 부모님 기력이 떨어질 수 있으니 안부를 자주 여쭙고, 병원 가실 일이 있으면 모시고 가게.",
   "8": "돈은 들어오는데 곁에 걱정이 한 자락 드리우는 달이야. 그래도 윗사람 쪽에서 좋은 소식이 내려와 끝은 밝네. 내 일에 큰 변화가 없어도 자식에게 기쁜 일이 생길 수 있으니 가족 얼굴을 자주 살피며 지내게.",
