   "8": "뜻밖의 돈이 집안에 들어오는 달일세. 이리저리 뛰느라 바쁘겠지만 남의 말다툼에는 한 발짝도 들이지 말게. 말 한마디가 꼬투리가 될 수 있으니 그것만 지키면 무난히 지나가네.",
