   "11": "문밖보다 집 안이 편한 달이야. 남의 다툼에 끼면 손해만 보니 모른 척 비켜서게. 잃어버리는 물건이 생기기 쉬우니 가방과 지갑을 자주 살피고, 몸이 무겁다 싶으면 일찍 잠자리에 들게.",
