   "5": "봄 뜰의 꽃이 활짝 웃는 듯 먹을 복이 넉넉하고 꾀하는 일마다 이익이 붙는 달이야. 기운이 좋을 때 미뤄 둔 일을 앞당겨 처리하게. 흥이 날 때 일을 몰아서 하면 술술 끝나네.",
   "6": "물을 만난 고기처럼 신이 나는 달일세. 집안 식구들이 오순도순 지내고 품었던 소원이 열매를 맺네. 기쁨이 클수록 가족과 나누게. 오랜만에 온 식구가 한 상에 둘러앉는 자리를 마련해 보게.",
   "7": "하늘이 자네를 돕는 듯 좋은 일이 끊이지 않는 달일세. 남쪽으로 가면 돈이 붙고 일터에서 이익이 생기네. 동쪽과 서쪽 모두에 기쁜 일이 있으니 새 일을 시작하려던 참이면 이달에 첫걸음을 떼게.",
