   "5": "다칠 일은 없지만 몸이 몹시 고된 달이야. 그래도 애쓴 보람이 있으니 한탄하지 말게. 처음엔 어려워도 뒤는 좋고 서쪽에서 도와주는 사람이 우연히 찾아오니 반갑게 맞게. 흘린 땀은 거짓말을 하지 않네.",
   "6": "말썽이 많고 관공서 일이 마음에 걸리는 달일세. 말다툼에 끼지 말고 남과 다투지 말게. 이성을 가까이하면 몸이 지칠 수 있으니 조심하고, 칭찬만 무성하고 실속 없는 일은 거절하게.",
