   "9": "돈이 될 기회가 문밖에 흩어져 있어 나서야 만나는 달일세. 단비를 맞은 풀처럼 일이 살아나고 가는 곳마다 반기는 얼굴이 있네. 바깥 약속을 부지런히 잡으면 자네 얼굴에도 생기가 돌 걸세.",
