   "6": "하는 일은 두루 잘 풀리는데 걱정이 불쑥불쑥 드는 달일세. 친한 사람과 한 번쯤 부딪치고 배우자 몸이 무거워질 수 있으니 집안일을 나눠 들고 쉬게 해 주게. 한 걸음 양보하면 다툼이 반으로 줄어드네.",
