   "5": "집안 분위기가 거칠어져 식구끼리 언성이 높아지는 달일세. 형제 사이가 멀어지거나 가깝던 이웃과 헤어질 수 있네. 벌여 둔 일은 이달에 마무리하고 말은 한 번 더 삼키게. 화난 말은 하룻밤 재운 뒤에 꺼내게.",
   "6": "때가 맞지 않아 괜한 기대에 마음만 상하는 달이야. 분주히 뛰어도 원하는 돈은 오지 않네. 서쪽에 사는 사람이 손해를 끼칠 수 있으니 그쪽과의 거래는 미뤄 두게. 기대를 낮추면 마음이 덜 다치네.",
