   "10": "마음에 걱정이 많아 홀로 괴로운 달이야. 몸도 편치 않아 기운이 자주 처지니 쉬는 시간을 따로 떼어 두게. 부드럽고 자라나는 사람을 만나면 뜻밖의 돈이 들어오니 반가운 인연이야. 괴로움은 혼자 삭이지 말고 털어놓게.",
